def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def strip_ns(tag: str) -> str:
        if "}" in tag:
            return tag.split("}", 1)[1]
        return tag

    def handle_xml(xml_text: str) -> None:
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            return
        for tc in root.iter():
            if strip_ns(tc.tag) != "testcase":
                continue
            name = (tc.get("name") or "").strip()
            classname = (tc.get("classname") or "").strip()
            if not name and not classname:
                continue
            test_name = name
            if classname:
                test_name = f"{classname}.{name}" if name else classname
            status = "pass"
            for child in list(tc):
                tag = strip_ns(child.tag).lower()
                if tag in ("failure", "error"):
                    status = "fail"
                    break
                if tag == "skipped":
                    status = "skip"
            results[test_name] = status

    if not log:
        return results

    cleaned = log.replace("\x00", "")
    # Prefer full <testsuites> blocks if present
    blocks = re.findall(r"<testsuites[\s\S]*?</testsuites>", cleaned)
    if blocks:
        for block in blocks:
            block = re.sub(r"<\?xml[^>]*\?>", "", block).strip()
            handle_xml(block)
    else:
        # Fallback to individual <testsuite> blocks
        suites = re.findall(r"<testsuite[\s\S]*?</testsuite>", cleaned)
        for block in suites:
            block = re.sub(r"<\?xml[^>]*\?>", "", block).strip()
            handle_xml(block)

    return results
